-- Explicit project only. No account creation; fixture writes are rolled back.
begin;
select set_config('request.jwt.claim.sub',(select id::text from auth.users where email_confirmed_at is not null order by created_at desc limit 1),true);
select set_config('request.jwt.claims',json_build_object('sub',current_setting('request.jwt.claim.sub'),'role','authenticated')::text,true);
set local role authenticated;
do $$ declare page uuid;other_page uuid;first jsonb;second jsonb;third jsonb;id uuid;data jsonb;stamp timestamptz;before_notes text;req uuid=gen_random_uuid();begin
 page=public.manage_page(null,'Import tests','',false);
 other_page=public.manage_page(null,'Other page','',false);
 first=public.commit_import(req,page,null,'append','one.csv','[{"business_name":"Same name","phone":"+12025550101","google_maps_url":"https://maps.google.com/?cid=one","notes":"Preserve"},{"business_name":"Same name","phone":"+12025550101"},{"business_name":"Same name","phone":"+12025550101"}]',3,0);
 if (first->>'imported')::int<>3 then raise exception 'NULL Maps/name/phone preservation failed';end if;
 if public.commit_import(req,page,null,'append','one.csv','[{"business_name":"Retry"}]',1,0)<>first then raise exception 'Request retry not idempotent';end if;
 raise notice 'PASS: Import appends all NULL Maps duplicates and retries idempotently';
 second=public.commit_import(gen_random_uuid(),other_page,null,'append','duplicates.csv','[{"business_name":"Different name","google_maps_url":"https://maps.google.com/?cid=one","notes":"Overwrite"},{"business_name":"A","google_maps_url":"https://maps.google.com/?cid=new"},{"business_name":"B","google_maps_url":"https://maps.google.com/?cid=new"}]',3,0);
 if (second->>'imported')::int<>1 or (second->>'duplicates')::int<>2 then raise exception 'Exact Maps across pages/in-file failed';end if;
 if not exists(select 1 from public.leads where notes='Preserve') then raise exception 'Original changed';end if;
 raise notice 'PASS: Only exact Maps URLs skip across pages and within a batch';
 if public.preview_import('["https://maps.google.com/?cid=one",null,"https://maps.google.com/?cid=z","https://maps.google.com/?cid=z"]')<>2 then raise exception 'Preview duplicate count wrong';end if;
 third=public.commit_import(gen_random_uuid(),page,null,'replace','replace.csv','[{"business_name":"Same Maps new name","google_maps_url":"https://maps.google.com/?cid=one"},{"business_name":"Replacement"}]',3,1);
 if (third->>'replaced')::int<>2 or (third->>'duplicates')::int<>1 or (third->>'invalid')::int<>1 then raise exception 'Replacement counts wrong';end if;
 data=public.workspace_leads(page);
 if (data->>'total')::int<>2 then raise exception 'Replacement visibility wrong';end if;
 begin perform public.undo_import((first->>'id')::uuid);raise exception 'Out of order undo succeeded';exception when raise_exception then if sqlerrm='Out of order undo succeeded' then raise;end if;end;
 perform public.undo_import((third->>'id')::uuid);
 if (public.workspace_leads(page)->>'total')::int<>3 then raise exception 'Replace undo failed to restore all originals';end if;
 perform public.undo_import((third->>'id')::uuid);
 raise notice 'PASS: Replace preserves same-URL originals, restores prior records, and undo is idempotent';
 select l.id,l.updated_at into id,stamp from public.leads l where import_id=(first->>'id')::uuid limit 1;
 perform public.save_lead(id,stamp,'{"notes":"Edited after import"}');
 begin perform public.undo_import((first->>'id')::uuid);raise exception 'Unsafe undo succeeded';exception when raise_exception then if sqlerrm='Unsafe undo succeeded' then raise;end if;end;
 begin perform public.save_lead(id,stamp,'{"notes":"Stale overwrite"}');raise exception 'Stale save succeeded';exception when serialization_failure then null;end;
 raise notice 'PASS: Post-import edits block undo and stale writes fail';
 perform public.undo_import((second->>'id')::uuid);
 if (public.workspace_leads(other_page)->>'total')::int<>0 then raise exception 'Append undo failed';end if;
 second=public.commit_import(gen_random_uuid(),other_page,null,'append','retry-after-undo.csv','[{"business_name":"Reimported","google_maps_url":"https://maps.google.com/?cid=new"}]',1,0);
 if (second->>'imported')::int<>1 then raise exception 'Undo prevents reimport';end if;
 raise notice 'PASS: Append undo removes its unchanged rows and permits safe reimport';
 begin perform public.commit_import(gen_random_uuid(),other_page,null,'replace','bad.csv','[{"business_name":""}]',1,0);raise exception 'Invalid replacement succeeded';exception when check_violation then null;end;
 if (public.workspace_leads(other_page)->>'total')::int<>1 then raise exception 'Failed replacement destroyed original rows';end if;
 raise notice 'PASS: Invalid replacement rolls back all visibility changes atomically';
 select l.id,l.updated_at into id,stamp from public.leads l where import_id=(second->>'id')::uuid;
 perform public.save_lead(id,stamp,'{}','delete');
 if (public.workspace_leads(other_page)->>'total')::int<>0 then raise exception 'Lead deletion visibility failed';end if;
 perform public.manage_page(other_page,'Renamed page','updated',false);
 perform public.manage_page(other_page,null,'',true);
 if exists(select 1 from jsonb_array_elements(public.workspace_pages()) p where p->>'id'=other_page::text) then raise exception 'Deleted page visible';end if;
 raise notice 'PASS: Lead editing/deletion and page rename/deletion use authorized records';
 -- Batch performance and actual server-side paging/filtering at the target scale.
 select jsonb_agg(jsonb_build_object('business_name','Scale '||n,'phone',case when n%2=0 then '+1 202 555 0199' else '' end)) into data from generate_series(1,4001)n;
 second=public.commit_import(gen_random_uuid(),null,'Scale test','new','scale.csv',data,4001,0);
 if (second->>'imported')::int<>4001 then raise exception 'Scale import failed';end if;
 data=public.workspace_leads((second->>'pageId')::uuid,'page','Scale','all',true,'name',8,8);
 if jsonb_array_length(data->'rows')<>8 or (data->>'total')::int<>2000 then raise exception 'Server pagination or Has Phone failed';end if;
 data=public.workspace_leads((second->>'pageId')::uuid,'page','12025550199','all',false,'newest',0,8);
 if (data->>'total')::int<>2000 then raise exception 'Normalized phone search failed';end if;
 perform public.undo_import((second->>'id')::uuid);
 raise notice 'PASS: 4001-row import, 8-row pagination, Has Phone and normalized search';
 second=public.commit_import(gen_random_uuid(),page,null,'append','called.csv','[{"business_name":"Called after import"}]',1,0);
 select l.id into id from public.leads l where import_id=(second->>'id')::uuid;
 insert into public.call_attempts(lead_id,outcome) values(id,'no_answer');
 begin perform public.undo_import((second->>'id')::uuid);raise exception 'Calling history lost';exception when raise_exception then if sqlerrm='Calling history lost' then raise;end if;end;
 raise notice 'PASS: Calling history blocks unsafe import undo';
 perform set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000004',true);
 begin perform public.undo_import((first->>'id')::uuid);raise exception 'Foreign undo accepted';exception when insufficient_privilege then null;end;
 begin perform public.manage_page(page,'Unauthorized','',false);raise exception 'Foreign page edit accepted';exception when insufficient_privilege then null;end;
 raise notice 'PASS: Cross-owner import undo and page management are denied';
end $$;
reset role;
select json_build_object('phase3_rpc_checks','passed','scale_import_rows',4001,'fixtures','transaction rollback') as verification;
rollback;
